#!/usr/bin/env node
// Copyright (c) 2026 Spencer Williams
// Licensed under the MIT License.

// Writes the minified copies of the converter's scripts and stylesheet that
// index.html loads, each with an external source map pointing back at the
// readable file beside it.
//
// The site is served straight from the repository by GitHub Pages, with no
// build step, so the minified files are committed. tests/min-assets.test.js
// rebuilds them in memory and fails if a committed copy is stale: after editing
// any source listed below, run `npm run build:min` and commit the result.
//
// Never edit a .min file by hand. Edit the source and rebuild.
//
// esbuild is pinned to an exact version in package.json because its output
// is what the freshness test compares byte for byte. Bump it by hand and
// rebuild in the same commit.
//
//   node scripts/build-min.js          write every minified file
//   node scripts/build-min.js --watch  rebuild a file whenever its source changes

const fs = require('fs');
const path = require('path');
const esbuild = require('esbuild');

const ROOT = path.join(__dirname, '..');

// The sources index.html loads. The format pages still load the readable
// files; only the converter is minified.
const SOURCES = [
    'lib/floating-point.js',
    'src/theme.js',
    'src/mode.js',
    'src/url-state.js',
    'src/ui.js',
    'src/webmcp.js',
    'style.css',
];

function minPath(source) {
    return source.replace(/\.(js|css)$/, '.min.$1');
}

// Build one source in memory. Returns the minified text and its source map,
// exactly as they are committed.
function buildMin(source) {
    const input = fs.readFileSync(path.join(ROOT, source), 'utf8');
    const loader = source.endsWith('.css') ? 'css' : 'js';
    const outName = path.basename(minPath(source));
    const result = esbuild.transformSync(input, {
        loader,
        minify: true,
        // Top-level names stay as they are: every script on the page is a
        // classic script sharing one global scope, and ui.js calls into
        // floating-point.js and url-state.js by name. esbuild only renames
        // top-level bindings when it bundles or wraps the output, and this
        // does neither.
        sourcemap: 'external',
        sourcefile: path.basename(source),
        // The readable source is also served next to the map, but embedding it
        // keeps the map self-contained: Lighthouse's source-map audit warns
        // without it. Maps are only fetched by DevTools, never by the page.
        sourcesContent: true,
        // The license headers are ordinary comments, which minification drops.
        banner: `/* ${source} - generated by scripts/build-min.js, do not edit. ` +
            'Copyright (c) Spencer Williams, MIT License. */',
        // legalComments defaults differ between loaders; drop them uniformly
        // and rely on the banner.
        legalComments: 'none',
        // The CSS is minified only. esbuild lowers syntax for its default
        // target unless told otherwise, so tell it to leave everything as is.
        target: 'esnext',
    });
    const comment = loader === 'css'
        ? `\n/*# sourceMappingURL=${outName}.map */\n`
        : `\n//# sourceMappingURL=${outName}.map\n`;
    return {
        code: result.code.replace(/\n$/, '') + comment,
        map: result.map,
    };
}

function writeMin(source) {
    const { code, map } = buildMin(source);
    const out = path.join(ROOT, minPath(source));
    fs.writeFileSync(out, code);
    fs.writeFileSync(out + '.map', map);
    return out;
}

function main(argv) {
    for (const source of SOURCES) {
        const out = writeMin(source);
        console.log(`${source} -> ${path.relative(ROOT, out)}`);
    }
    if (argv.includes('--watch')) {
        console.log('Watching for changes...');
        for (const source of SOURCES) {
            fs.watch(path.join(ROOT, source), () => {
                try {
                    writeMin(source);
                    console.log(`rebuilt ${minPath(source)}`);
                } catch (err) {
                    console.error(`${source}: ${err.message}`);
                }
            });
        }
    }
}

if (require.main === module) {
    main(process.argv.slice(2));
}

module.exports = { SOURCES, minPath, buildMin };
